<?php use app\services\Ui;use app\services\Catalog;use yii\helpers\Html;$personal=Yii::$app->user->identity->role==='teacher';$this->title=$personal?'Mening natijalarim':'Reyting va hisobot';$r=Yii::$app->request; ?>
<div class="page-heading"><div><span class="eyebrow">TASDIQLANGAN NATIJALAR</span><h1><?= $personal?'Mening natijalarim':'Reyting va hisobot' ?></h1><p><?= $personal?'O‘z arizalaringizning holati va yakuniy tasdiqlangan natijalaringiz.':'Xodimlar natijalarini davr, toifa va bo‘lim kesimida ko‘ring.' ?></p></div><div class="actions no-print"><?= Html::a('Tasdiqlangan ballar · Excel ↓',array_merge(['kpi/reports'],$r->get(),['format'=>'xlsx']),['class'=>'button secondary']) ?><?= Html::a('Tasdiqlangan ballar · CSV ↓',array_merge(['kpi/reports'],$r->get(),['format'=>'csv']),['class'=>'button secondary']) ?><button class="button" onclick="window.print()">Chop etish / PDF</button></div></div>
<section class="card"><?= Html::beginForm(['kpi/reports'],'get',['class'=>'filters no-print']) ?><?php if(!$personal): ?><?= Ui::select('Hisobot kesimi','group',$group,['employee'=>'Xodimlar','department'=>'Kafedralar','unit'=>'Bo‘limlar','faculty'=>'Fakultetlar',... (\app\services\Access::isGlobal(Yii::$app->user->identity)?['university'=>'Universitet jami']:[])]) ?><?php endif ?><?= Ui::select('Davr','period',$r->get('period'),[''=>'Barcha davrlar']+array_column($periods,'name','id')) ?><?php if(!$personal): ?><?= Ui::select('Toifa','category',$r->get('category'),[''=>'Barcha toifalar']+Catalog::CATEGORIES) ?><?= Ui::select('Bo‘lim','org',$r->get('org'),[''=>'Barcha bo‘limlar']+array_column($orgs,'name','id')) ?><?php endif ?><button class="button secondary">Hisobotni tuzish</button><?= Html::endForm() ?></section>
<?= $this->render('_report_applications',compact('activityRows','activityTotal','activityPage','personal')) ?>
<section class="card report-results"><div class="card-heading"><h2><?= Ui::h($personal?'Shaxsiy tasdiqlangan natijalar':['employee'=>'Xodimlar reytingi','department'=>'Kafedralar reytingi','unit'=>'Bo‘limlar reytingi','faculty'=>'Fakultetlar reytingi','university'=>'Universitet natijasi'][$group]) ?></h2><span class="muted"><?= date('d.m.Y H:i') ?></span></div><?php if(!$rows): ?><?= Ui::empty('Tanlangan shartlar bo‘yicha tasdiqlangan natijalar yo‘q.') ?><?php else: ?><div class="table-wrap"><table><thead><tr><th><?= $personal?'№':'O‘rin' ?></th><th><?= $personal?'Xodim':'Xodim / bo‘lim' ?></th><th>Bo‘lim</th><th>Toifa</th><th class="number">Arizalar</th><th class="number">Ball</th></tr></thead><tbody><?php foreach($rows as $i=>$row): ?><tr><td><span class="rank"><?= $i+1 ?></span></td><td><b><?= Ui::h($row['employee']??'Belgilanmagan') ?></b></td><td><?= Ui::h($row['org']??'—') ?></td><td><?= Ui::h(Catalog::CATEGORIES[$row['category']]??$row['category']) ?></td><td class="number"><?= (int)$row['applications'] ?></td><td class="number score"><?= Ui::money($row['score_cents']) ?></td></tr><?php endforeach ?></tbody><tfoot><tr><td colspan="5">Jami tasdiqlangan ball</td><td class="number score"><?= Ui::money(array_sum(array_column($rows,'score_cents'))) ?></td></tr></tfoot></table></div><?php endif ?></section><p class="muted">Foydalanuvchi huquqlari doirasidagi natijalar ko‘rsatiladi. PDF uchun chop etish oynasida “PDF sifatida saqlash”ni tanlang.</p>
